import numpy as np


class HardwareProfile:
    """Hardware constraints for NAS."""

    def __init__(self, max_params=1e6, max_latency_ms=10, max_memory_mb=256,
                 mac_units=1024, peak_bandwidth_gbps=50):
        self.max_params = max_params
        self.max_latency_ms = max_latency_ms
        self.max_memory_mb = max_memory_mb
        self.mac_units = mac_units
        self.peak_bandwidth_gbps = peak_bandwidth_gbps


class ArchitectureCandidate:
    """Represents a neural architecture candidate."""

    def __init__(self, layers):
        self.layers = layers  # list of dicts
        self.accuracy = 0.0
        self.latency = 0.0
        self.params = 0
        self.memory = 0

    def estimate_params(self):
        """Estimate total parameters."""
        total = 0
        for layer in self.layers:
            if layer['type'] == 'conv2d':
                total += layer['c_in'] * layer['c_out'] * layer['k'] * layer['k']
            elif layer['type'] == 'linear':
                total += layer['in'] * layer['out']
        self.params = total
        return total

    def estimate_latency(self, hardware):
        """Estimate inference latency on target hardware."""
        total_cycles = 0
        for layer in self.layers:
            if layer['type'] == 'conv2d':
                ops = 2 * layer['h'] * layer['w'] * layer['c_in'] * layer['c_out'] * layer['k'] * layer['k']
                cycles = ops / hardware.mac_units
                total_cycles += cycles
            elif layer['type'] == 'linear':
                ops = 2 * layer['in'] * layer['out']
                cycles = ops / hardware.mac_units
                total_cycles += cycles

        # Assume 300 MHz clock
        self.latency = (total_cycles / 300e6) * 1000  # ms
        return self.latency

    def estimate_memory(self):
        """Estimate peak memory usage in MB."""
        peak = 0
        current = 0
        for layer in self.layers:
            if layer['type'] == 'conv2d':
                activation = layer['h'] * layer['w'] * layer['c_out'] * 4  # bytes
                weights = layer['c_in'] * layer['c_out'] * layer['k'] * layer['k'] * 4
                current = activation + weights
            elif layer['type'] == 'linear':
                current = layer['out'] * 4 + layer['in'] * layer['out'] * 4
            peak = max(peak, current)
        self.memory = peak / (1024 * 1024)  # MB
        return self.memory

    def check_feasibility(self, hardware):
        """Check if architecture meets hardware constraints."""
        self.estimate_params()
        self.estimate_latency(hardware)
        self.estimate_memory()

        return (
            self.params <= hardware.max_params and
            self.latency <= hardware.max_latency_ms and
            self.memory <= hardware.max_memory_mb
        )


class HardwareAwareNAS:
    """Hardware-aware Neural Architecture Search."""

    def __init__(self, hardware_profile, search_space):
        self.hardware = hardware_profile
        self.search_space = search_space
        self.best_architecture = None
        self.best_score = -float('inf')

    def _random_architecture(self):
        """Generate random architecture from search space."""
        n_layers = np.random.randint(2, 6)
        layers = []

        for _ in range(n_layers):
            layer_type = np.random.choice(['conv2d', 'linear'])
            if layer_type == 'conv2d':
                layers.append({
                    'type': 'conv2d',
                    'h': np.random.choice([7, 14, 28]),
                    'w': np.random.choice([7, 14, 28]),
                    'c_in': np.random.choice([16, 32, 64]),
                    'c_out': np.random.choice([16, 32, 64]),
                    'k': np.random.choice([3, 5])
                })
            else:
                layers.append({
                    'type': 'linear',
                    'in': np.random.choice([64, 128, 256]),
                    'out': np.random.choice([32, 64, 128])
                })

        return ArchitectureCandidate(layers)

    def _evaluate_architecture(self, arch, accuracy_predictor):
        """Evaluate architecture with hardware constraints."""
        if not arch.check_feasibility(self.hardware):
            return -float('inf')

        # TODO: Predict accuracy using surrogate model
        predicted_accuracy = accuracy_predictor(arch)

        # TODO: Multi-objective score: accuracy - latency_penalty
        latency_penalty = (arch.latency / self.hardware.max_latency_ms) * 0.1
        score = predicted_accuracy - latency_penalty

        return score

    def search(self, n_iterations=100, accuracy_predictor=None):
        """Run NAS search."""
        if accuracy_predictor is None:
            def accuracy_predictor(arch):
                # Simple surrogate: more params = better accuracy (diminishing returns)
                return 0.5 + 0.3 * np.log10(arch.params + 1) / np.log10(self.hardware.max_params + 1)

        history = []

        for i in range(n_iterations):
            arch = self._random_architecture()
            score = self._evaluate_architecture(arch, accuracy_predictor)

            history.append({
                'iteration': i,
                'params': arch.params,
                'latency': arch.latency,
                'score': score,
                'feasible': score > -float('inf')
            })

            if score > self.best_score:
                self.best_score = score
                self.best_architecture = arch

        return self.best_architecture, history

    def pareto_frontier(self, candidates):
        """Find Pareto-optimal architectures (accuracy vs latency)."""
        pareto = []
        for arch in candidates:
            dominated = False
            for other in candidates:
                if (other.accuracy >= arch.accuracy and
                    other.latency <= arch.latency and
                    (other.accuracy > arch.accuracy or other.latency < arch.latency)):
                    dominated = True
                    break
            if not dominated:
                pareto.append(arch)
        return pareto


if __name__ == "__main__":
    np.random.seed(42)
    hardware = HardwareProfile(
        max_params=5e6, max_latency_ms=5.0,
        max_memory_mb=128, mac_units=1024
    )

    nas = HardwareAwareNAS(hardware, search_space='default')
    best, history = nas.search(n_iterations=50)

    print(f"Best architecture score: {nas.best_score:.4f}")
    print(f"Params: {best.params:.0f}")
    print(f"Latency: {best.latency:.2f} ms")
    print(f"Memory: {best.memory:.2f} MB")
    print(f"Layers: {len(best.layers)}")

    feasible = [h for h in history if h['feasible']]
    print(f"\nFeasible architectures: {len(feasible)}/{len(history)}")
